import "./chart.css";

const MetricsChart = () => {
  return (
    <div className="metrics-container">
      <div className="chart-card">
        <h3 className="chart-title">Metrics Overview</h3>
        <div className="chart-placeholder">
          <p>[Overview of Metrics with Line chart]</p>
        </div>
      </div>
    </div>
  );
};

export default MetricsChart;
